import{_ as t,o as a,c as s,ag as r}from"./chunks/framework.2cFhd8Ux.js";const p=JSON.parse('{"title":"CS [4xxx]/[5xxx] Engineering Software with AI","description":"","frontmatter":{"source":"SYLLABUS.md"},"headers":[],"relativePath":"SYLLABUS.md","filePath":"SYLLABUS.md"}'),n={name:"SYLLABUS.md"};function i(o,e,d,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="cs-4xxx5xxx-engineering-software-with-ai" tabindex="-1">CS [4xxx]/[5xxx] Engineering Software with AI <a class="header-anchor" href="#cs-4xxx5xxx-engineering-software-with-ai" aria-label="Permalink to &quot;CS [4xxx]/[5xxx] Engineering Software with AI&quot;">​</a></h1><p>3 credits</p><p>[Semester and year, as scheduled]</p><h2 id="instructor" tabindex="-1">Instructor <a class="header-anchor" href="#instructor" aria-label="Permalink to &quot;Instructor&quot;">​</a></h2><ul><li><strong>Name:</strong> [name]</li><li><strong>Email:</strong> [email]</li><li><strong>Phone:</strong> [phone]</li><li><strong>Office hours:</strong> [days, times and place]</li><li><strong>Class meetings:</strong> [days, times and room]; two 75-minute meetings a week, a Seminar and a Lab</li></ul><p>Email response time: normally within 24 hours on weekdays, possibly longer over weekends and holidays.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>CS 3383 Software Engineering. The course builds on its requirements, design, testing and team practices and does not teach them again. Students should be comfortable with git, the command line, and Python or JavaScript. No experience with coding agents is needed, and the lower-division course <a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/" target="_blank" rel="noreferrer">Building Apps with AI</a> is not a prerequisite.</p><h2 id="course-description" tabindex="-1">Course Description <a class="header-anchor" href="#course-description" aria-label="Permalink to &quot;Course Description&quot;">​</a></h2><p>This course examines how software is engineered when coding agents write much of the code. Students learn how large language model (LLM) coding agents work, how to give them context through specifications, <code>AGENTS.md</code> files and the Model Context Protocol (MCP), and how to secure them. The course then covers spec-driven development, tests as oracles and measured test adequacy, changes to legacy code, code review at scale, supply-chain security, LLM-based features and their evaluation, parallel and background agents, and the published evidence on AI in software engineering. Each week pairs a Seminar on concepts, readings and debate with a hands-on Lab. Throughout the semester, teams work in a class fork of a real open-source codebase: they specify contributions, delegate parts of the work to agents, and verify the results to the standard a maintainer would expect. Grades rest on evidence of verification and on each student&#39;s ability to explain their own work without AI.</p><h2 id="required-textbooks-and-materials" tabindex="-1">Required Textbooks and Materials <a class="header-anchor" href="#required-textbooks-and-materials" aria-label="Permalink to &quot;Required Textbooks and Materials&quot;">​</a></h2><p>No textbook. Weekly readings are listed in the <a href="./resources/reading-list.html">reading list</a>. Students need a laptop with a modern browser and several free accounts; the required cost is $0 (<a href="./TOOLS.html">Tool Handout</a>). Before the first Seminar, students complete the <a href="./setup/">week 0 setup</a>, which takes about 90 minutes.</p><h2 id="learning-outcomes" tabindex="-1">Learning Outcomes <a class="header-anchor" href="#learning-outcomes" aria-label="Permalink to &quot;Learning Outcomes&quot;">​</a></h2><p>At the end of this course, students will be able to:</p><ul><li>Explain how LLM coding agents work, including the model, context, tools, the agent loop, permissions and sandboxes, and run, read and extend a minimal agent.</li><li>Apply context engineering through specifications, <code>AGENTS.md</code> files and MCP tools, and measure whether agents follow them.</li><li>Evaluate AI-written code with tests whose adequacy is measured by property-based and mutation testing and enforced in continuous integration, and review AI-authored pull requests, AI reviewers and static analysis against known defects.</li><li>Change large existing codebases safely through comprehension, characterization tests and refactoring, and contribute changes that reviewers accept.</li><li>Analyze and reduce the security risks of AI-assisted development, including prompt injection, supply-chain attacks, leaked secrets and excessive permissions, and act responsibly toward users, maintainers and licenses.</li><li>Build and evaluate LLM-based features with structured outputs and calibrated evals, accounting for cost and latency, and assess published evidence about AI in software engineering.</li></ul><h2 id="course-outline" tabindex="-1">Course Outline <a class="header-anchor" href="#course-outline" aria-label="Permalink to &quot;Course Outline&quot;">​</a></h2><p>The course follows a standard 16-week semester. Weeks 1–15 are teaching weeks; week 16 is finals week, when the final defense takes place in the scheduled final exam slot.</p><table tabindex="0"><thead><tr><th>Week</th><th>Topic</th><th>Key concepts</th></tr></thead><tbody><tr><td>1</td><td><a href="./weeks/01-agentic-engineering/">From Vibe Coding to Agentic Engineering</a></td><td>Vibe coding versus agentic engineering; Specify, Delegate, Verify; observed and inferred claims; tokens, context and sampling; tool calling; the agent loop</td></tr><tr><td>2</td><td><a href="./weeks/02-inside-agents/">Inside Real Agents</a></td><td>Harness architecture; how prompts and tool schemas are assembled; context management; approval prompts versus real boundaries; reading a large codebase outside in</td></tr><tr><td>3</td><td><a href="./weeks/03-context-engineering/">Context Engineering</a></td><td>The context window as the agent&#39;s whole world; context rot; <code>AGENTS.md</code>, rules and skills; MCP servers and tools; measuring compliance</td></tr><tr><td>4</td><td><a href="./weeks/04-securing-agents/">Securing Agents</a></td><td>Prompt injection; the lethal trifecta; tool poisoning; allowlists, approvals, egress blocks and sandboxes; secrets out of reach; threat models</td></tr><tr><td>5</td><td><a href="./weeks/05-spec-driven-development/">Spec-Driven Development</a></td><td><code>SPEC.md</code>, <code>DESIGN.md</code> and <code>TASKS.md</code>; EARS acceptance criteria; edge cases; plan mode; agent-sized tasks; specs that change</td></tr><tr><td>6</td><td><a href="./weeks/06-tests-as-oracles/">Tests as Oracles</a></td><td>Test oracles; writing the check first; property-based testing and shrinking; biased generators; bug reports as reproductions</td></tr><tr><td>7</td><td><a href="./weeks/07-test-adequacy/">Measuring Test Adequacy</a></td><td>Coverage versus mutation score; mutants and survivors; equivalent mutants; how scores get gamed; what mutation score cannot show</td></tr><tr><td>8</td><td><a href="./weeks/08-legacy-code/">Legacy Code</a></td><td>Characterization and approval tests; seams; what &quot;behavior unchanged&quot; means; small green refactoring steps; the strangler fig</td></tr><tr><td>9</td><td><a href="./weeks/09-review-at-scale/">Review at Scale</a></td><td>Reviewing AI-authored pull requests; review burden; AI reviewers and precision; comments people act on; static analysis; CI gates</td></tr><tr><td>10</td><td><a href="./weeks/10-supply-chain/">Supply Chain and Secure Code</a></td><td>Insecure-but-working code; exploit tests; slopsquatting; dependency confusion; install scripts; secrets in git history; provenance and SBOMs</td></tr><tr><td>11</td><td><a href="./weeks/11-llm-features/">Building LLM Features</a></td><td>Structured outputs and validation; valid versus correct; retries and repair; tool calling; cost and latency budgets; retrieval basics</td></tr><tr><td>12</td><td><a href="./weeks/12-evals/">Evals</a></td><td>Evals as experiments; failure modes; calibrating an LLM judge with Cohen&#39;s kappa; regression gates in CI; thresholds as targets; benchmark limits</td></tr><tr><td>13</td><td><a href="./weeks/13-parallel-agents/">Parallel and Background Agents</a></td><td>Merge points; git worktrees; background and cloud agents; orchestration cost; conflicts that merge cleanly; governance controls</td></tr><tr><td>14</td><td><a href="./weeks/14-evidence-and-responsibility/">Evidence and Responsibility</a></td><td>Measured versus perceived productivity; study design; contributor AI policies; disclosure over detection; licensing and provenance; a structured debate</td></tr><tr><td>15</td><td><a href="./weeks/15-ship-and-reflect/">Ship and Reflect</a></td><td>Where the field is going; verification as the work; changing norms; integration sprint; defense dry run; graduate study talks</td></tr><tr><td>16</td><td><a href="./weeks/16-final-defense/">Final Defense</a></td><td>Finals week: team demo with a live reproducible check; individual questions with AI off; final report and peer evaluation 3</td></tr></tbody></table><h2 id="evaluation-procedures" tabindex="-1">Evaluation Procedures <a class="header-anchor" href="#evaluation-procedures" aria-label="Permalink to &quot;Evaluation Procedures&quot;">​</a></h2><h3 id="assessment" tabindex="-1">Assessment <a class="header-anchor" href="#assessment" aria-label="Permalink to &quot;Assessment&quot;">​</a></h3><p>Grades are based on evidence: commit history, the AI log (<code>AI_LOG.md</code>), tests and checks that anyone can reproduce, an honest account of limitations, and explanations given without AI.</p><table tabindex="0"><thead><tr><th>Component</th><th>CS [4xxx]</th><th>CS [5xxx]</th></tr></thead><tbody><tr><td>Labs and assignments (weeks 1–13, lowest week dropped, plus the PR round)</td><td>35%</td><td>30%</td></tr><tr><td>Due-date quizzes (weeks 2–14, lowest two dropped)</td><td>10%</td><td>5%</td></tr><tr><td>Team project (M0 15, M1 30, M2 40 and Final 65 points)</td><td>30%</td><td>25%</td></tr><tr><td>Oral exams (weeks 8 and 14, 7.5% each)</td><td>15%</td><td>15%</td></tr><tr><td>Reading responses and Seminar participation</td><td>10%</td><td>5%</td></tr><tr><td>Graduate work</td><td>0%</td><td>20%</td></tr></tbody></table><p>The <a href="./assessment/">assessment guide</a> is part of this syllabus. It contains the rubrics, the conversion of points to grades, and the rules on <a href="./assessment/#absences-and-make-up-work">attendance, absences and make-up work</a>.</p><h3 id="final-examination" tabindex="-1">Final Examination <a class="header-anchor" href="#final-examination" aria-label="Permalink to &quot;Final Examination&quot;">​</a></h3><p>There is no written final examination. The final defense takes place in the course&#39;s scheduled two-hour final exam slot in week 16. Each team gives a six-minute demonstration of its contribution, including a live check that anyone could reproduce, and answers a question as a team. Each member then answers individual questions about their own work without AI. The defense is worth 30 of the Final milestone&#39;s 65 points (10 for the team demonstration and 20 for the individual questions), and taking it is required for a grade of C or higher (<a href="./project/final-defense.html">final defense</a>). The final report, the third peer evaluation and the CS [5xxx] final paper are due at 11:59 pm on the last day of finals week.</p><h3 id="performance-standards-and-grading-policy" tabindex="-1">Performance Standards and Grading Policy <a class="header-anchor" href="#performance-standards-and-grading-policy" aria-label="Permalink to &quot;Performance Standards and Grading Policy&quot;">​</a></h3><p>Letter grades are A (90–100%), B (80–89%), C (70–79%), D (60–69%) and F (below 60%), without plus or minus grades (catalog Regulation E). A grade of C or higher also requires taking both oral exams and the final defense (<a href="./assessment/#letter-grades">details</a>).</p><h3 id="assignments" tabindex="-1">Assignments <a class="header-anchor" href="#assignments" aria-label="Permalink to &quot;Assignments&quot;">​</a></h3><ul><li>Labs and assignments: weeks 1–13 each have a Lab checkoff and a take-home assignment, due before the next week&#39;s Seminar (by default at 11:59 pm the night before). In weeks 9 and 10, each student also opens a pull request on another team&#39;s fork during <a href="./project/pr-round.html">the PR round</a>.</li><li>Due-date quizzes: a seven-minute quiz, taken without AI, opens the Seminar in weeks 2–14 and covers the work just submitted (<a href="./assessment/quizzes.html">quizzes</a>).</li><li>Team project: teams of three or four work in the class codebase all semester. The milestones are M0 (week 5), M1 (week 8), M2 (week 12) and the Final (finals week), with peer evaluations at M1, M2 and the Final (<a href="./project/">team project</a>; <a href="./project/milestones.html">milestones</a>).</li><li>Oral exams: two individual 15-minute exams without AI, in weeks 8 and 14 (<a href="./assessment/oral-exams.html">oral exams</a>).</li><li>Reading responses: 150 to 250 words on each week&#39;s reading, written without AI.</li></ul><p>Graded personal writing, including reading responses, reflections, peer evaluations, the final report and all graduate writing, is submitted on Canvas and never placed in a repository (<a href="./assessment/#privacy-of-your-work">privacy of your work</a>). Students who fall behind should first complete each lab&#39;s &quot;Minimum to keep up&quot; section and tell their team early.</p><h3 id="late-work-policy" tabindex="-1">Late Work Policy <a class="header-anchor" href="#late-work-policy" aria-label="Permalink to &quot;Late Work Policy&quot;">​</a></h3><p>Each student has two grace tokens; each extends one individual deadline by 48 hours, with no reason required. Each team has one team token for M0, M1 or M2. Beyond that, late work loses 10% of its points per day for up to three days. Tokens do not apply to quizzes, oral exams, the PR round, the final defense or other live events, which have their own make-up rules, and running out of free tool credits does not justify a late submission. The full rules are under <a href="./assessment/#late-work-and-grace-tokens">late work and grace tokens</a>.</p><h2 id="undergraduate-and-graduate-course-expectations" tabindex="-1">Undergraduate and Graduate Course Expectations <a class="header-anchor" href="#undergraduate-and-graduate-course-expectations" aria-label="Permalink to &quot;Undergraduate and Graduate Course Expectations&quot;">​</a></h2><p>CS [4xxx] and CS [5xxx] students attend the same Seminars and Labs and complete the same core work: every lab and assignment, the due-date quizzes, both oral exams, the team project and the final defense. Teams may include students from both levels. Graduate students are expected to show greater depth by presenting and critiquing research and by running an empirical study of their own, as the catalog requires for joint-listed courses (&quot;Additional projects/assignments required for graduate credit&quot;). For this reason the shared components carry less weight in the CS [5xxx] grade, and the graduate work makes up the remaining 20%.</p><h3 id="undergraduate-students-cs-4xxx" tabindex="-1">Undergraduate Students (CS [4xxx]) <a class="header-anchor" href="#undergraduate-students-cs-4xxx" aria-label="Permalink to &quot;Undergraduate Students (CS [4xxx])&quot;">​</a></h3><p>Undergraduates complete the shared work, weighted as in the CS [4xxx] column of the assessment table. In weeks with a graduate paper presentation, they post one question about the paper on Canvas before the Seminar, written without AI; this counts toward Seminar participation. The expected workload is about 8.5 hours a week: two 75-minute meetings and about six hours outside class.</p><h3 id="graduate-students-cs-5xxx" tabindex="-1">Graduate Students (CS [5xxx]) <a class="header-anchor" href="#graduate-students-cs-5xxx" aria-label="Permalink to &quot;Graduate Students (CS [5xxx])&quot;">​</a></h3><p>Graduate students complete all of the shared work and about 1.5 additional hours a week of graduate work, worth 20% of their grade (<a href="./graduate/">graduate work</a>):</p><ul><li>a 20-minute presentation of a paper from the graduate seminar list in one Seminar between weeks 3 and 14, and one turn as discussant with three prepared questions (6%: 4.5% for the presentation and 1.5% for the discussant role);</li><li>a critique of one paper in about 1,000 words, or a tool experience report, due before the week 13 Seminar (3%);</li><li>a small empirical study at no cost, alone or in a pair, that replicates or extends published work: a protocol in week 6, interim results in week 11, a draft in week 14, a 10-minute talk in week 15 and a four- to six-page paper in ACM format in finals week (11%). Studies may not involve human subjects without IRB approval.</li></ul><p>In addition to the common outcomes, graduate students will be able to:</p><ul><li>Analyze and present research in AI for software engineering, judging what a paper shows, how strong its evidence is and what it means for practice.</li><li>Design and run a small empirical study and report it in a short paper.</li></ul><h2 id="ai-use" tabindex="-1">AI Use <a class="header-anchor" href="#ai-use" aria-label="Permalink to &quot;AI Use&quot;">​</a></h2><p>AI tools are a required part of this course. Students direct coding agents and are graded on whether they can specify, verify, secure and explain the result. Every task carries one of three labels: AI on, AI limited or AI off. Quizzes, oral exams, the individual questions at the final defense, reading responses, reflections, peer evaluations, signed pull request descriptions and review comments, and graduate critiques are always AI off. Students are responsible for understanding, validating and explaining all work they submit; work a student cannot explain does not count as their own. AI help is disclosed in <code>AI_LOG.md</code>, in an <code>Assisted-by: [tool and model]</code> line in commit messages, and in the AI section of each pull request. The complete rules are in the <a href="./assessment/#ai-use-policy">AI use policy</a>, and the <a href="./setup/safety-contract.html">agent safety contract</a> governs how agents may be used.</p><h2 id="academic-honesty" tabindex="-1">Academic Honesty <a class="header-anchor" href="#academic-honesty" aria-label="Permalink to &quot;Academic Honesty&quot;">​</a></h2><p>Academic honesty is important at the University of Idaho because it is the way you improve over time. Academic dishonesty, which includes cheating and plagiarism, is not tolerated at the University of Idaho.</p><p>Plagiarism means claiming another&#39;s work as your own. That can happen in several ways:</p><ul><li>Copying another&#39;s work in whole or in part</li><li>Quoting another&#39;s work without attribution</li><li>Paraphrasing another&#39;s work without attribution</li><li>Purchasing another&#39;s work from &quot;study aid&quot; websites</li></ul><p>In this course it also includes using AI where a task is marked AI off, and hiding AI help that the <a href="#ai-use">AI Use</a> rules ask you to disclose. Suspected academic dishonesty is handled under the University&#39;s Student Code of Conduct and Resolution Process (FSH 2300), which includes reporting it to the Dean of Students. If you have any questions about how to cite a source or credit an AI tool, please ask me.</p><h2 id="university-of-idaho-classroom-learning-civility-clause" tabindex="-1">University of Idaho Classroom Learning Civility Clause <a class="header-anchor" href="#university-of-idaho-classroom-learning-civility-clause" aria-label="Permalink to &quot;University of Idaho Classroom Learning Civility Clause&quot;">​</a></h2><p>In any environment in which people gather to learn, it is essential that all members feel as free and safe as possible in their participation. To this end, it is expected that everyone in this course will be treated with mutual respect and civility, with an understanding that all of us (students, instructors, professors, guests, and teaching assistants) will be respectful and civil to one another in discussion, in action, in teaching, and in learning.</p><p>Should you feel our classroom interactions do not reflect an environment of civility and respect, you are encouraged to meet with your instructor during office hours to discuss your concern. Additional resources for expression of concern or requesting support include the <a href="https://www.uidaho.edu/student-resources/dean-of-students" target="_blank" rel="noreferrer">Dean of Students</a> office and staff, the UI <a href="https://www.uidaho.edu/student-resources/health-wellness/counseling-mental-health-center" target="_blank" rel="noreferrer">Counseling and Mental Health Center</a>, or the UI <a href="https://www.uidaho.edu/civil-rights" target="_blank" rel="noreferrer">Office of Civil Rights and Investigations</a>.</p><h2 id="center-for-disability-access-and-resources" tabindex="-1">Center for Disability Access and Resources <a class="header-anchor" href="#center-for-disability-access-and-resources" aria-label="Permalink to &quot;Center for Disability Access and Resources&quot;">​</a></h2><p>University of Idaho&#39;s Center for Disability Access and Resources recommends that faculty and instructors include on all syllabi a statement informing students with disabilities of their right to request reasonable accommodations in the classroom.</p><p>Center for Disability Access and Resources (CDAR) coordinates services to meet the educational needs of students with temporary or permanent disabilities. CDAR works with students and faculty to arrange reasonable accommodations and promote an environment that is inclusive for all learners.</p><p>Students with disabilities needing accommodations to fully participate in this class should contact the Center for Disability Access and Resources (CDAR). All accommodations must be approved through CDAR prior to being implemented. To learn more about the accommodation process, visit CDAR&#39;s website at <a href="https://www.uidaho.edu/cdar" target="_blank" rel="noreferrer">www.uidaho.edu/cdar</a> or call 208-885-6307.</p><h2 id="firearms" tabindex="-1">Firearms <a class="header-anchor" href="#firearms" aria-label="Permalink to &quot;Firearms&quot;">​</a></h2><p>The University of Idaho bans firearms from its property with only limited exceptions. One exception applies to persons who hold a valid Idaho enhanced concealed carry license, provided those firearms remain concealed at all times. If an enhanced concealed carry license holder&#39;s firearm is displayed, other than in necessary self-defense, it is a violation of University policy. Please contact local law enforcement (call 911) to report firearms on University property. University of Idaho leadership remains committed to maintaining a safe work, living and learning environment on campus. We will not tolerate any threatening use of firearms or any other weapons. While authorized license holders may have familiarity and be at ease carrying a loaded firearm, we ask that they be aware that many people are not familiar with handguns and are uncomfortable in their presence.</p><h2 id="student-resources" tabindex="-1">Student Resources <a class="header-anchor" href="#student-resources" aria-label="Permalink to &quot;Student Resources&quot;">​</a></h2><p>The University of Idaho provides student support to ensure a successful learning experience: <a href="https://www.uidaho.edu/student-resources" target="_blank" rel="noreferrer">UofI Student Resources</a>.</p><ul><li><strong>SI-PASS (Peer Assisted Study Sessions):</strong> regularly scheduled, peer-led study sessions for difficult courses (<a href="https://www.uidaho.edu/student-resources/academic-support/peer-assisted-study-sessions" target="_blank" rel="noreferrer">SI-PASS</a>).</li><li><strong>Library help:</strong> the <a href="https://www.lib.uidaho.edu/" target="_blank" rel="noreferrer">UofI Library website</a> has many databases that will help you find relevant and reliable books, articles, images, and more. Don&#39;t hesitate to contact a librarian for research assistance.</li><li><strong>Technology help:</strong> the OIT <a href="https://www.uidaho.edu/student-resources/technical-support" target="_blank" rel="noreferrer">IT Service Desk</a> provides technology-related services to students. Phone: 208-885-HELP (208-885-4357). Requests: <a href="https://support.uidaho.edu/" target="_blank" rel="noreferrer">support.uidaho.edu</a>.</li><li><strong>Writing support:</strong> the <a href="https://www.uidaho.edu/student-resources/academic-support/writing-center" target="_blank" rel="noreferrer">UofI Writing Center</a> provides one-on-one assistance to student writers and other members of the campus community. Phone: 208-885-6644.</li><li><strong>Student Success Program (SSP):</strong> in-house resources specifically for students living in the residence halls. Academic Peer Mentors provide free tutoring and academic support Sundays–Thursdays from 2:00 pm to 10:00 pm. SSP is located in the Wallace Residence Center basement. Students do not need to live in the Wallace Residence Center to use this resource.</li><li><strong>Vandal Food Pantry:</strong> a <a href="https://www.uidaho.edu/student-resources/dean-of-students/basic-needs-food-insecurity-resources" target="_blank" rel="noreferrer">free resource</a> stocked weekly with food, grocery bags, and various hygiene items, open to all. Please take what you need.</li><li><strong>Green Dot Safety Program:</strong> Vandal Green Dot helps students learn about the power of the bystander, how to recognize potentially risky situations, and realistic ways to intervene. Learn more and get involved through the UI <a href="https://www.uidaho.edu/student-resources/health-wellness/violence-prevention-center" target="_blank" rel="noreferrer">Green Dot Safety Program</a> or by emailing <a href="mailto:greendot@uidaho.edu" target="_blank" rel="noreferrer">greendot@uidaho.edu</a>.</li></ul><h2 id="uofi-moscow-land-acknowledgement" tabindex="-1">UofI Moscow Land Acknowledgement <a class="header-anchor" href="#uofi-moscow-land-acknowledgement" aria-label="Permalink to &quot;UofI Moscow Land Acknowledgement&quot;">​</a></h2><p>UofI Moscow is located on the homelands of the Nimiipuu (Nez Perce), Palus (Palouse) and Schitsu&#39;umsh (Coeur d&#39;Alene) tribes. We extend gratitude to the indigenous people that call this place home, since time immemorial. UofI recognizes that it is our academic responsibility to build relationships with the indigenous people to ensure integrity of tribal voices.</p>',62)])])}const m=t(n,[["render",i]]);export{p as __pageData,m as default};
